"use strict";
import { Interface } from "@ethersproject/abi";
export class GaugeBatchedStakingService {
  /**
   * Builds batched transaction requests for V3 approve + stake
   * @param params.nftManagerAddress - NFT Position Manager contract address
   * @param params.gaugeAddress - Gauge contract address
   * @param params.tokenId - NFT token ID to stake
   * @param params.account - User address
   * @param params.chainId - Chain ID
   * @returns Array of validated transaction requests for batching
   */
  buildBatchedV3StakeTransaction(params) {
    const { nftManagerAddress, gaugeAddress, tokenId, account, chainId } = params;
    const nftManagerInterface = new Interface([
      {
        inputs: [
          { internalType: "address", name: "operator", type: "address" },
          { internalType: "bool", name: "approved", type: "bool" }
        ],
        name: "setApprovalForAll",
        outputs: [],
        stateMutability: "nonpayable",
        type: "function"
      }
    ]);
    const gaugeInterface = new Interface([
      {
        inputs: [{ internalType: "uint256", name: "tokenId", type: "uint256" }],
        name: "deposit",
        outputs: [],
        stateMutability: "nonpayable",
        type: "function"
      }
    ]);
    const approvalTx = {
      to: nftManagerAddress,
      from: account,
      data: nftManagerInterface.encodeFunctionData("setApprovalForAll", [gaugeAddress, true]),
      value: "0x0",
      chainId,
      type: 2
      // EIP-1559
    };
    const depositTx = {
      to: gaugeAddress,
      from: account,
      data: gaugeInterface.encodeFunctionData("deposit", [BigInt(tokenId)]),
      value: "0x0",
      chainId,
      type: 2
      // EIP-1559
    };
    return [approvalTx, depositTx];
  }
  /**
   * Builds batched transaction requests for V2 approve + stake
   * @param params.lpTokenAddress - LP token (pool) contract address
   * @param params.gaugeAddress - Gauge contract address
   * @param params.amount - Amount of LP tokens to stake
   * @param params.account - User address
   * @param params.chainId - Chain ID
   * @returns Array of validated transaction requests for batching
   */
  buildBatchedV2StakeTransaction(params) {
    const { lpTokenAddress, gaugeAddress, amount, account, chainId } = params;
    const erc20Interface = new Interface([
      {
        inputs: [
          { internalType: "address", name: "spender", type: "address" },
          { internalType: "uint256", name: "amount", type: "uint256" }
        ],
        name: "approve",
        outputs: [{ internalType: "bool", name: "", type: "bool" }],
        stateMutability: "nonpayable",
        type: "function"
      }
    ]);
    const gaugeInterface = new Interface([
      {
        inputs: [{ internalType: "uint256", name: "_amount", type: "uint256" }],
        name: "deposit",
        outputs: [],
        stateMutability: "nonpayable",
        type: "function"
      }
    ]);
    const MAX_UINT256 = BigInt("0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff");
    const approvalTx = {
      to: lpTokenAddress,
      from: account,
      data: erc20Interface.encodeFunctionData("approve", [gaugeAddress, MAX_UINT256]),
      value: "0x0",
      chainId,
      type: 2
      // EIP-1559
    };
    const depositTx = {
      to: gaugeAddress,
      from: account,
      data: gaugeInterface.encodeFunctionData("deposit", [amount]),
      value: "0x0",
      chainId,
      type: 2
      // EIP-1559
    };
    return [approvalTx, depositTx];
  }
  /**
   * Builds batched transaction requests for approve + unstake
   * Note: Unstaking doesn't require approval, so this is just for symmetry
   * In practice, unstaking only needs a single transaction
   */
  buildBatchedUnstakeTransaction(params) {
    const { gaugeAddress, tokenId, account, chainId } = params;
    const gaugeInterface = new Interface([
      {
        inputs: [{ internalType: "uint256", name: "tokenId", type: "uint256" }],
        name: "withdraw",
        outputs: [],
        stateMutability: "nonpayable",
        type: "function"
      }
    ]);
    const withdrawTx = {
      to: gaugeAddress,
      from: account,
      data: gaugeInterface.encodeFunctionData("withdraw", [BigInt(tokenId)]),
      value: "0x0",
      chainId,
      type: 2
      // EIP-1559
    };
    return [withdrawTx];
  }
}
